struct DeepPackageMaterialTextures {
  baseRow0: vec4f,
  baseRow1: vec4f,
  mrRow0: vec4f,
  mrRow1: vec4f,
  occlusionRow0: vec4f,
  occlusionRow1: vec4f,
  normalRow0: vec4f,
  normalRow1: vec4f,
  emissiveRow0: vec4f,
  emissiveRow1: vec4f,
};
@group(1) @binding(0) var deepBaseColorMap: texture_2d<f32>;
@group(1) @binding(1) var deepBaseColorSampler: sampler;
@group(1) @binding(2) var deepMetallicRoughnessMap: texture_2d<f32>;
@group(1) @binding(3) var deepMetallicRoughnessSampler: sampler;
@group(1) @binding(4) var<uniform> deepMaterialTextures: DeepPackageMaterialTextures;
@group(1) @binding(5) var deepOcclusionMap: texture_2d<f32>;
@group(1) @binding(6) var deepOcclusionSampler: sampler;
@group(1) @binding(7) var deepNormalMap: texture_2d<f32>;
@group(1) @binding(8) var deepNormalSampler: sampler;
@group(1) @binding(9) var deepEmissiveMap: texture_2d<f32>;
@group(1) @binding(10) var deepEmissiveSampler: sampler;
fn deepPackageSlotUv(uv0: vec2f, uv1: vec2f, row0: vec4f, row1: vec4f) -> vec2f {
  let uv = vec3f(select(uv0, uv1, row0.w > 1.5), 1.0);
  return vec2f(
    dot(row0.xyz, uv),
    dot(row1.xyz, uv),
  );
}
fn deepPackageSafeNormalize(value: vec3f, fallback: vec3f) -> vec3f {
  let lengthSquared = dot(value, value);
  return select(fallback, value * inverseSqrt(max(lengthSquared, 0.00000001)), lengthSquared > 0.00000001);
}
fn deepPackageTangentFallback(normal: vec3f) -> vec3f {
  let axis = select(vec3f(1.0, 0.0, 0.0), vec3f(0.0, 1.0, 0.0), abs(normal.x) > 0.9);
  return deepPackageSafeNormalize(cross(axis, normal), vec3f(0.0, 0.0, 1.0));
}
fn deepPackageMappedNormal(
  geometricNormal: vec3f,
  tangentInput: vec4f,
  modelHandedness: f32,
  uv0: vec2f,
  uv1: vec2f,
) -> vec3f {
  let normalUv = deepPackageSlotUv(
    uv0, uv1, deepMaterialTextures.normalRow0, deepMaterialTextures.normalRow1,
  );
  let sourceTangent = deepPackageSafeNormalize(
    tangentInput.xyz - geometricNormal * dot(geometricNormal, tangentInput.xyz),
    deepPackageTangentFallback(geometricNormal),
  );
  let sourceHandedness = tangentInput.w * modelHandedness;
  let sourceBitangent = cross(geometricNormal, sourceTangent) * sourceHandedness;
  let determinant = deepMaterialTextures.normalRow0.x * deepMaterialTextures.normalRow1.y
    - deepMaterialTextures.normalRow0.y * deepMaterialTextures.normalRow1.x;
  let determinantSign = select(-1.0, 1.0, determinant >= 0.0);
  let tangent = deepPackageSafeNormalize(
    (sourceTangent * deepMaterialTextures.normalRow1.y
      - sourceBitangent * deepMaterialTextures.normalRow1.x) * determinantSign,
    deepPackageTangentFallback(geometricNormal),
  );
  let bitangent = cross(geometricNormal, tangent) * sourceHandedness * determinantSign;
  let sampled = textureSample(deepNormalMap, deepNormalSampler, normalUv).rgb * 2.0 - 1.0;
  let tangentNormal = deepPackageSafeNormalize(
    vec3f(sampled.xy * deepMaterialTextures.normalRow1.w, sampled.z), vec3f(0.0, 0.0, 1.0),
  );
  return deepPackageSafeNormalize(
    tangent * tangentNormal.x + bitangent * tangentNormal.y + geometricNormal * tangentNormal.z,
    geometricNormal,
  );
}
// Deep Shader IR schema 1; generated deterministically.
struct DeepPbrFrame {
  view: mat4x4f,
  light: mat4x4f,
  eye: vec4f,
  background: vec4f,
  floor: vec4f,
  lightDirection: vec4f,
  tuning: vec4f,
};
@group(0) @binding(0) var<uniform> deepPbrFrame: DeepPbrFrame;
@group(0) @binding(1) var deepShadowMap: texture_depth_2d_array;
@group(0) @binding(2) var deepShadowSampler: sampler_comparison;
@group(0) @binding(3) var deepSpecularEnvironment: texture_cube<f32>;
@group(0) @binding(4) var deepDiffuseEnvironment: texture_cube<f32>;
@group(0) @binding(5) var deepBrdfLut: texture_2d<f32>;
@group(0) @binding(6) var deepEnvironmentSampler: sampler;
const DEEP_PI: f32 = 3.141592653589793;
fn deepSafeNormalize(value: vec3f, fallback: vec3f) -> vec3f {
  let lengthSquared = dot(value, value);
  let normalized = value * inverseSqrt(max(lengthSquared, 0.00000001));
  return select(fallback, normalized, lengthSquared > 0.00000001);
}
fn deepFresnelSchlick(cosine: f32, f0: vec3f) -> vec3f {
  return f0 + (vec3f(1.0) - f0) * pow(1.0 - cosine, 5.0);
}
fn deepDistributionGgx(nDotH: f32, roughness: f32) -> f32 {
  let alpha = roughness * roughness;
  let alpha2 = alpha * alpha;
  let denominator = nDotH * nDotH * (alpha2 - 1.0) + 1.0;
  return alpha2 / max(DEEP_PI * denominator * denominator, 0.000001);
}
fn deepGeometrySchlickGgx(nDotX: f32, roughness: f32) -> f32 {
  let k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
  return nDotX / max(nDotX * (1.0 - k) + k, 0.0001);
}
















fn deepLowerStandardPbr(worldPosition: vec3f, baseInput: vec3f, normalInput: vec3f, metallicInput: f32, roughnessInput: f32, occlusionInput: f32, emission: vec3f, alphaInput: f32) -> vec4f {
  let baseColor = max(baseInput, vec3f(0.0));
  let normal = deepSafeNormalize(normalInput, vec3f(0.0, 1.0, 0.0));
  let view = deepSafeNormalize(deepPbrFrame.eye.xyz - worldPosition, vec3f(0.0, 0.0, 1.0));
  let light = deepSafeNormalize(deepPbrFrame.lightDirection.xyz, vec3f(0.0, 1.0, 0.0));
  let halfVector = deepSafeNormalize(view + light, normal);
  let metallic = clamp(metallicInput, 0.0, 1.0);
  let roughness = clamp(roughnessInput, 0.045, 1.0);
  let nDotL = clamp(dot(normal, light), 0.0, 1.0);
  let nDotV = clamp(dot(normal, view), 0.0001, 1.0);
  let nDotH = clamp(dot(normal, halfVector), 0.0, 1.0);
  let vDotH = clamp(dot(view, halfVector), 0.0, 1.0);
  let f0 = mix(vec3f(0.04), baseColor, metallic);
  let fresnel = deepFresnelSchlick(vDotH, f0);
  let distribution = deepDistributionGgx(nDotH, roughness);
  let geometry = deepGeometrySchlickGgx(nDotV, roughness) * deepGeometrySchlickGgx(nDotL, roughness);
  let specular = distribution * geometry * fresnel / max(4.0 * nDotV * nDotL, 0.0001);
  let diffuse = (vec3f(1.0) - fresnel) * (1.0 - metallic) * baseColor / DEEP_PI;
  let shadow = deepShadowVisibility(worldPosition, normal, nDotL);
  let directRadiance = vec3f(2.5, 2.4, 2.25);
  let direct = (diffuse + specular) * directRadiance * nDotL * shadow;
  let occlusion = clamp(occlusionInput, 0.0, 1.0);
  let indirectFresnel = f0 + (max(vec3f(1.0 - roughness), f0) - f0) * pow(1.0 - nDotV, 5.0);
  let irradiance = textureSampleLevel(deepDiffuseEnvironment, deepEnvironmentSampler, normal, 0.0).rgb;
  let indirectDiffuse = (vec3f(1.0) - indirectFresnel) * (1.0 - metallic) * baseColor * irradiance;
  let reflection = reflect(-view, normal);
  let maxSpecularLod = f32(textureNumLevels(deepSpecularEnvironment) - 1u);
  let radiance = textureSampleLevel(deepSpecularEnvironment, deepEnvironmentSampler, reflection, roughness * maxSpecularLod).rgb;
  let dfg = textureSampleLevel(deepBrdfLut, deepEnvironmentSampler, vec2f(nDotV, roughness), 0.0).rg;
  let energyCompensation = vec3f(1.0) + f0 * (1.0 / max(dfg.x + dfg.y, 0.05) - 1.0);
  let indirectSpecular = radiance * (f0 * dfg.x + dfg.y) * energyCompensation;
  let color = direct + (indirectDiffuse + indirectSpecular) * occlusion + emission;
  return vec4f(max(color, vec3f(0.0)), clamp(alphaInput, 0.0, 1.0));
}
struct DeepVertexInput {
  @location(0) a_position: vec3f,
  @location(1) a_normal: vec3f,
  @location(2) a_modelRow0: vec4f,
  @location(3) a_modelRow1: vec4f,
  @location(4) a_modelRow2: vec4f,
  @location(5) a_normalColumn0: vec4f,
  @location(6) a_normalColumn1: vec4f,
  @location(7) a_normalColumn2: vec4f,
  @location(8) a_colorMetal: vec4f,
  @location(9) a_material: vec4f,
  @location(10) a_uv0: vec2f,
  @location(11) a_tangent: vec4f,
  @location(12) a_emissiveAlpha: vec4f,
  @location(13) a_uv1: vec2f,
};
struct DeepVertexOut {
  @builtin(position) position: vec4f,
  @location(0) v_worldPosition: vec3f,
  @location(1) v_normalWorld: vec3f,
  @location(2) v_surfaceColorMetal: vec4f,
  @location(3) v_surfaceMaterial: vec4f,
  @location(4) v_surfaceEmissiveAlpha: vec4f,
  @location(5) v_surfaceUv0: vec2f,
  @location(6) v_surfaceUv1: vec2f,
  @location(7) v_surfaceTangent: vec4f,
};
@vertex fn vertexNormalMapped(input: DeepVertexInput) -> DeepVertexOut {
  var output: DeepVertexOut;
  let n_pbrFrameView: mat4x4f = deepPbrFrame.view;
  let n_worldBasis0: vec3f = vec3f(1.0, 0.0, 0.0);
  let n_modelRow0: vec4f = input.a_modelRow0;
  let n_position: vec3f = input.a_position;
  let n_one: f32 = 1.0;
  let n_position4: vec4f = vec4f(n_position, n_one);
  let n_worldComponent0: f32 = dot(n_modelRow0, n_position4);
  let n_worldAxis0: vec3f = n_worldBasis0 * vec3f(n_worldComponent0);
  let n_worldBasis1: vec3f = vec3f(0.0, 1.0, 0.0);
  let n_modelRow1: vec4f = input.a_modelRow1;
  let n_worldComponent1: f32 = dot(n_modelRow1, n_position4);
  let n_worldAxis1: vec3f = n_worldBasis1 * vec3f(n_worldComponent1);
  let n_worldPosition01: vec3f = n_worldAxis0 + n_worldAxis1;
  let n_worldBasis2: vec3f = vec3f(0.0, 0.0, 1.0);
  let n_modelRow2: vec4f = input.a_modelRow2;
  let n_worldComponent2: f32 = dot(n_modelRow2, n_position4);
  let n_worldAxis2: vec3f = n_worldBasis2 * vec3f(n_worldComponent2);
  let n_worldPosition: vec3f = n_worldPosition01 + n_worldAxis2;
  let n_clipPosition: vec4f = n_pbrFrameView * vec4f(n_worldPosition, 1.0);
  let n_normalColumn0: vec4f = input.a_normalColumn0;
  let n_normalBasis0: vec3f = n_normalColumn0.xyz;
  let n_normal: vec3f = input.a_normal;
  let n_normalComponent0: f32 = n_normal.x;
  let n_normalAxis0: vec3f = n_normalBasis0 * vec3f(n_normalComponent0);
  let n_normalColumn1: vec4f = input.a_normalColumn1;
  let n_normalBasis1: vec3f = n_normalColumn1.xyz;
  let n_normalComponent1: f32 = n_normal.y;
  let n_normalAxis1: vec3f = n_normalBasis1 * vec3f(n_normalComponent1);
  let n_normalWorld01: vec3f = n_normalAxis0 + n_normalAxis1;
  let n_normalColumn2: vec4f = input.a_normalColumn2;
  let n_normalBasis2: vec3f = n_normalColumn2.xyz;
  let n_normalComponent2: f32 = n_normal.z;
  let n_normalAxis2: vec3f = n_normalBasis2 * vec3f(n_normalComponent2);
  let n_normalWorldRaw: vec3f = n_normalWorld01 + n_normalAxis2;
  let n_normalWorld: vec3f = normalize(n_normalWorldRaw);
  let n_colorMetal: vec4f = input.a_colorMetal;
  let n_material: vec4f = input.a_material;
  let n_emissiveAlpha: vec4f = input.a_emissiveAlpha;
  let n_uv0: vec2f = input.a_uv0;
  let n_uv1: vec2f = input.a_uv1;
  let n_tangentWorldBasis0: vec3f = vec3f(1.0, 0.0, 0.0);
  let n_tangent: vec4f = input.a_tangent;
  let n_tangentDirection: vec3f = n_tangent.xyz;
  let n_zero: f32 = 0.0;
  let n_tangentDirection4: vec4f = vec4f(n_tangentDirection, n_zero);
  let n_tangentWorldComponent0: f32 = dot(n_modelRow0, n_tangentDirection4);
  let n_tangentWorldAxis0: vec3f = n_tangentWorldBasis0 * vec3f(n_tangentWorldComponent0);
  let n_tangentWorldBasis1: vec3f = vec3f(0.0, 1.0, 0.0);
  let n_tangentWorldComponent1: f32 = dot(n_modelRow1, n_tangentDirection4);
  let n_tangentWorldAxis1: vec3f = n_tangentWorldBasis1 * vec3f(n_tangentWorldComponent1);
  let n_tangentWorld01: vec3f = n_tangentWorldAxis0 + n_tangentWorldAxis1;
  let n_tangentWorldBasis2: vec3f = vec3f(0.0, 0.0, 1.0);
  let n_tangentWorldComponent2: f32 = dot(n_modelRow2, n_tangentDirection4);
  let n_tangentWorldAxis2: vec3f = n_tangentWorldBasis2 * vec3f(n_tangentWorldComponent2);
  let n_tangentWorldDirection: vec3f = n_tangentWorld01 + n_tangentWorldAxis2;
  let n_tangentSign: f32 = n_tangent.w;
  let n_tangentWorld: vec4f = vec4f(n_tangentWorldDirection, n_tangentSign);
  output.position = n_clipPosition;
  output.v_worldPosition = n_worldPosition;
  output.v_normalWorld = n_normalWorld;
  output.v_surfaceColorMetal = n_colorMetal;
  output.v_surfaceMaterial = n_material;
  output.v_surfaceEmissiveAlpha = n_emissiveAlpha;
  output.v_surfaceUv0 = n_uv0;
  output.v_surfaceUv1 = n_uv1;
  output.v_surfaceTangent = n_tangentWorld;
  return output;
}
@fragment fn fragmentMaterial(input: DeepVertexOut, @builtin(front_facing) deepFrontFacing: bool) -> @location(0) vec4f {
  let n_colorMetal: vec4f = input.v_surfaceColorMetal;
  var deepBaseColorSample = vec4f(1.0);
  var deepMetallicRoughnessSample = vec4f(1.0);
  var deepOcclusionSample = 1.0;
  var deepEmissiveSample = vec3f(1.0);
  if (deepMaterialTextures.baseRow0.w > 0.5) {
    deepBaseColorSample = textureSample(
      deepBaseColorMap, deepBaseColorSampler,
      deepPackageSlotUv(input.v_surfaceUv0, input.v_surfaceUv1, deepMaterialTextures.baseRow0, deepMaterialTextures.baseRow1),
    );
  }
  if (deepMaterialTextures.mrRow0.w > 0.5) {
    deepMetallicRoughnessSample = textureSample(
      deepMetallicRoughnessMap, deepMetallicRoughnessSampler,
      deepPackageSlotUv(input.v_surfaceUv0, input.v_surfaceUv1, deepMaterialTextures.mrRow0, deepMaterialTextures.mrRow1),
    );
  }
  if (deepMaterialTextures.occlusionRow0.w > 0.5) {
    let deepSampledOcclusion = textureSample(
      deepOcclusionMap, deepOcclusionSampler,
      deepPackageSlotUv(input.v_surfaceUv0, input.v_surfaceUv1, deepMaterialTextures.occlusionRow0, deepMaterialTextures.occlusionRow1),
    ).r;
    deepOcclusionSample = 1.0 + deepMaterialTextures.occlusionRow1.w * (deepSampledOcclusion - 1.0);
  }
  if (deepMaterialTextures.emissiveRow0.w > 0.5) {
    deepEmissiveSample = textureSample(
      deepEmissiveMap, deepEmissiveSampler,
      deepPackageSlotUv(input.v_surfaceUv0, input.v_surfaceUv1, deepMaterialTextures.emissiveRow0, deepMaterialTextures.emissiveRow1),
    ).rgb;
  }
  let n_baseColor: vec3f = n_colorMetal.rgb * deepBaseColorSample.rgb;
  let n_normalInput: vec3f = input.v_normalWorld;
  let n_surfaceNormal: vec3f = normalize(n_normalInput);
  let n_metallic: f32 = n_colorMetal.a * deepMetallicRoughnessSample.b;
  let n_material: vec4f = input.v_surfaceMaterial;
  let n_roughness: f32 = n_material.x * deepMetallicRoughnessSample.g;
  let n_occlusion: f32 = deepOcclusionSample;
  let n_emissiveAlpha: vec4f = input.v_surfaceEmissiveAlpha;
  let n_emission: vec3f = n_emissiveAlpha.rgb * deepEmissiveSample * deepMaterialTextures.emissiveRow1.w;
  let n_alpha: f32 = n_emissiveAlpha.a * deepBaseColorSample.a;
  let deepPackageGltfFront = select(!deepFrontFacing, deepFrontFacing, n_material.z > 0.0);
  let deepPackageGeometricNormal = select(-n_surfaceNormal, n_surfaceNormal, deepPackageGltfFront);
  var deepPackageNormal = deepPackageGeometricNormal;
  if (deepMaterialTextures.normalRow0.w > 0.5) {
    deepPackageNormal = deepPackageMappedNormal(
      deepPackageGeometricNormal, input.v_surfaceTangent, n_material.z, input.v_surfaceUv0, input.v_surfaceUv1,
    );
  }
  return deepLowerStandardPbr(input.v_worldPosition, n_baseColor, deepPackageNormal, n_metallic, n_roughness, n_occlusion, n_emission, n_alpha);
}

struct DeepCascadedShadowData {
  matrices: array<mat4x4f, 4>,
  split_depths: vec4f,
  blend_starts: vec4f,
  texel_world: vec4f,
  params: vec4f,
  camera_forward: vec4f,
};
@group(0) @binding(7) var<uniform> deepCascadedShadow: DeepCascadedShadowData;
fn deepCascadeIndex(viewDepth: f32) -> u32 {
  let count = clamp(u32(deepCascadedShadow.params.x), 1u, 4u);
  for (var index = 0u; index < count; index++) {
    if (viewDepth <= deepCascadedShadow.split_depths[index]) { return index; }
  }
  return count - 1u;
}
fn deepSampleCascade(index: u32, world: vec3f, normal: vec3f, nDotL: f32) -> f32 {
  let receiver = world + normal * deepCascadedShadow.texel_world[index] * (1.0 - clamp(nDotL, 0.0, 1.0));
  let clip = deepCascadedShadow.matrices[index] * vec4f(receiver, 1.0);
  let projected = clip.xyz / clip.w;
  let uv = projected.xy * vec2f(0.5, -0.5) + 0.5;
  let inside = all(uv >= vec2f(0.0)) && all(uv <= vec2f(1.0)) && projected.z >= 0.0 && projected.z <= 1.0;
  if (!inside) { return 1.0; }
  var visibility = 0.0;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      visibility += textureSampleCompareLevel(deepShadowMap, deepShadowSampler,
        uv + vec2f(f32(x), f32(y)) * deepCascadedShadow.params.z,
        i32(index), projected.z - deepCascadedShadow.params.y);
    }
  }
  return visibility / 9.0;
}
fn deepShadowVisibility(world: vec3f, normal: vec3f, nDotL: f32) -> f32 {
  let count = clamp(u32(deepCascadedShadow.params.x), 1u, 4u);
  let viewDepth = dot(world - deepPbrFrame.eye.xyz, deepCascadedShadow.camera_forward.xyz);
  if (viewDepth > deepCascadedShadow.split_depths[count - 1u]) { return 1.0; }
  let index = deepCascadeIndex(viewDepth);
  let current = deepSampleCascade(index, world, normal, nDotL);
  if (index + 1u >= count) { return current; }
  let blendStart = deepCascadedShadow.blend_starts[index];
  let split = deepCascadedShadow.split_depths[index];
  return mix(current, deepSampleCascade(index + 1u, world, normal, nDotL), smoothstep(blendStart, split, viewDepth));
}

struct DeepPackageMaterialTextures {
  baseRow0: vec4f,
  baseRow1: vec4f,
  mrRow0: vec4f,
  mrRow1: vec4f,
  occlusionRow0: vec4f,
  occlusionRow1: vec4f,
  normalRow0: vec4f,
  normalRow1: vec4f,
  emissiveRow0: vec4f,
  emissiveRow1: vec4f,
};
@group(1) @binding(0) var deepBaseColorMap: texture_2d<f32>;
@group(1) @binding(1) var deepBaseColorSampler: sampler;
@group(1) @binding(2) var deepMetallicRoughnessMap: texture_2d<f32>;
@group(1) @binding(3) var deepMetallicRoughnessSampler: sampler;
@group(1) @binding(4) var<uniform> deepMaterialTextures: DeepPackageMaterialTextures;
@group(1) @binding(5) var deepOcclusionMap: texture_2d<f32>;
@group(1) @binding(6) var deepOcclusionSampler: sampler;
@group(1) @binding(7) var deepNormalMap: texture_2d<f32>;
@group(1) @binding(8) var deepNormalSampler: sampler;
@group(1) @binding(9) var deepEmissiveMap: texture_2d<f32>;
@group(1) @binding(10) var deepEmissiveSampler: sampler;
fn deepPackageSlotUv(uv0: vec2f, uv1: vec2f, row0: vec4f, row1: vec4f) -> vec2f {
  let uv = vec3f(select(uv0, uv1, row0.w > 1.5), 1.0);
  return vec2f(
    dot(row0.xyz, uv),
    dot(row1.xyz, uv),
  );
}
fn deepPackageSafeNormalize(value: vec3f, fallback: vec3f) -> vec3f {
  let lengthSquared = dot(value, value);
  return select(fallback, value * inverseSqrt(max(lengthSquared, 0.00000001)), lengthSquared > 0.00000001);
}
fn deepPackageTangentFallback(normal: vec3f) -> vec3f {
  let axis = select(vec3f(1.0, 0.0, 0.0), vec3f(0.0, 1.0, 0.0), abs(normal.x) > 0.9);
  return deepPackageSafeNormalize(cross(axis, normal), vec3f(0.0, 0.0, 1.0));
}
fn deepPackageMappedNormal(
  geometricNormal: vec3f,
  tangentInput: vec4f,
  modelHandedness: f32,
  uv0: vec2f,
  uv1: vec2f,
) -> vec3f {
  let normalUv = deepPackageSlotUv(
    uv0, uv1, deepMaterialTextures.normalRow0, deepMaterialTextures.normalRow1,
  );
  let sourceTangent = deepPackageSafeNormalize(
    tangentInput.xyz - geometricNormal * dot(geometricNormal, tangentInput.xyz),
    deepPackageTangentFallback(geometricNormal),
  );
  let sourceHandedness = tangentInput.w * modelHandedness;
  let sourceBitangent = cross(geometricNormal, sourceTangent) * sourceHandedness;
  let determinant = deepMaterialTextures.normalRow0.x * deepMaterialTextures.normalRow1.y
    - deepMaterialTextures.normalRow0.y * deepMaterialTextures.normalRow1.x;
  let determinantSign = select(-1.0, 1.0, determinant >= 0.0);
  let tangent = deepPackageSafeNormalize(
    (sourceTangent * deepMaterialTextures.normalRow1.y
      - sourceBitangent * deepMaterialTextures.normalRow1.x) * determinantSign,
    deepPackageTangentFallback(geometricNormal),
  );
  let bitangent = cross(geometricNormal, tangent) * sourceHandedness * determinantSign;
  let sampled = textureSample(deepNormalMap, deepNormalSampler, normalUv).rgb * 2.0 - 1.0;
  let tangentNormal = deepPackageSafeNormalize(
    vec3f(sampled.xy * deepMaterialTextures.normalRow1.w, sampled.z), vec3f(0.0, 0.0, 1.0),
  );
  return deepPackageSafeNormalize(
    tangent * tangentNormal.x + bitangent * tangentNormal.y + geometricNormal * tangentNormal.z,
    geometricNormal,
  );
}
// Deep Shader IR schema 1; generated deterministically.
struct DeepPbrFrame {
  view: mat4x4f,
  light: mat4x4f,
  eye: vec4f,
  background: vec4f,
  floor: vec4f,
  lightDirection: vec4f,
  tuning: vec4f,
