  let n_normalBasis1: vec3f = n_normalColumn1.xyz;
  let n_normalComponent1: f32 = n_normal.y;
  let n_normalAxis1: vec3f = n_normalBasis1 * vec3f(n_normalComponent1);
  let n_normalWorld01: vec3f = n_normalAxis0 + n_normalAxis1;
